import bootstrap
import config
import util
import maze

def canonical_json_bytes(value: bootstrap.Any) -> bytes:
    return bootstrap.json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False, allow_nan=False).encode('utf-8')

def block_signing_payload(block: dict) -> bytes:
    unsigned = {key: value for key, value in block.items() if key not in maze.CONSENSUS_EXCLUDED_FIELDS}
    return canonical_json_bytes(unsigned)

def calculate_block_hash(block: dict) -> str:
    return bootstrap.hashlib.sha256(block_signing_payload(block)).hexdigest()

def sign_bytes(priv_hex: str, message: bytes) -> str:
    priv_int = int(priv_hex, 16)
    priv_key = bootstrap.ec.derive_private_key(priv_int, bootstrap.ec.SECP256K1())
    sig = priv_key.sign(message, bootstrap.ec.ECDSA(bootstrap.hashes.SHA256()))
    r, s = bootstrap.decode_dss_signature(sig)
    if s > config.SECP256K1_N // 2:
        s = config.SECP256K1_N - s
    return f'{r:064x}{s:064x}'

def verify_signature_bytes(pub_hex: str, message: bytes, sig_hex: str) -> bool:
    if not isinstance(sig_hex, str) or not bootstrap.re.fullmatch('[0-9a-fA-F]{128}', sig_hex):
        return False
    if not isinstance(pub_hex, str) or not bootstrap.re.fullmatch('04[0-9a-fA-F]{128}', pub_hex):
        return False
    try:
        if len(pub_hex) != 130 or not pub_hex.startswith('04'):
            return False
        x = int(pub_hex[2:66], 16)
        y = int(pub_hex[66:], 16)
        pub_nums = bootstrap.ec.EllipticCurvePublicNumbers(x, y, bootstrap.ec.SECP256K1())
        pub = pub_nums.public_key()
        r = int(sig_hex[:64], 16)
        s = int(sig_hex[64:], 16)
        if s > config.SECP256K1_N // 2:
            return False
        pub.verify(bootstrap.encode_dss_signature(r, s), message, bootstrap.ec.ECDSA(bootstrap.hashes.SHA256()))
        return True
    except Exception:
        return False

def seal_block(block: dict, private_key: str) -> dict:
    sealed = dict(block)
    sealed['hash'] = calculate_block_hash(sealed)
    sealed['signature'] = sign_bytes(private_key, bytes.fromhex(sealed['hash']))
    return sealed

def sign_message(priv_hex, message):
    if isinstance(message, str):
        message = message.encode('utf-8')
    return sign_bytes(priv_hex, message)

def verify_signature(pub_hex, message, sig_hex):
    if isinstance(message, str):
        message = message.encode('utf-8')
    return verify_signature_bytes(pub_hex, message, sig_hex)

def hash_block(b):
    return calculate_block_hash(b)

def hash_tx(tx):
    return bootstrap.hashlib.sha256(canonical_json_bytes(tx)).hexdigest()

def compute_merkle_root(tx_hashes: list) -> str:
    if not tx_hashes:
        return '0' * 64
    level = [bytes.fromhex(h[2:] if isinstance(h, str) and h[:2].lower() == '0x' else h) for h in tx_hashes]
    while len(level) > 1:
        carry = level.pop() if len(level) % 2 == 1 else None
        level = [bootstrap.eth_keccak(level[i] + level[i + 1]) for i in range(0, len(level), 2)]
        if carry is not None:
            level.append(carry)
    return level[0].hex()

def _s256(x: int) -> int:
    return x - (1 << 256) if x >= 1 << 255 else x
_WALLET_HEX = frozenset('0123456789abcdefABCDEF')

def _valid_wallet(addr) -> bool:
    if not isinstance(addr, str) or not addr.startswith('0x'):
        return False
    body = addr[2:]
    return len(body) >= 40 and all((c in _WALLET_HEX for c in body))
