def entropy_to_mnemonic(entropy: bytes) -> str:
    if len(entropy) * 8 not in (128, 160, 192, 224, 256):
        raise ValueError('entropy must be 128/160/192/224/256 bits')
    _hash = bootstrap.hashlib.sha256(bytes(entropy)).digest()
    _bits = ''.join((f'{_b:08b}' for _b in bytes(entropy)))
    _bits += ''.join((f'{_b:08b}' for _b in _hash))[:len(entropy) * 8 // 32]
    return ' '.join((_BIP39_WORDS[int(_bits[_i:_i + 11], 2)] for _i in range(0, len(_bits), 11)))

def validate_mnemonic(phrase) -> bool:
    try:
        if not isinstance(phrase, str):
            return False
        _words = phrase.split(' ')
        if len(_words) not in (12, 15, 18, 21, 24):
            return False
        _bits = ''.join((f'{_BIP39_WORDS.index(_w):011b}' for _w in _words))
    except (ValueError, AttributeError):
        return False
    _cs_len = len(_bits) // 33
    _ent_bits, _cs_bits = (_bits[:-_cs_len], _bits[-_cs_len:])
    _ent = int(_ent_bits, 2).to_bytes(len(_ent_bits) // 8, 'big')
    _expect = ''.join((f'{_b:08b}' for _b in bootstrap.hashlib.sha256(_ent).digest()))[:_cs_len]
    return _cs_bits == _expect

def generate_mnemonic(strength: int=128) -> str:
    if strength not in (128, 160, 192, 224, 256):
        raise ValueError('strength must be one of 128/160/192/224/256')
    return entropy_to_mnemonic(bootstrap.secrets.token_bytes(strength // 8))

def mnemonic_to_seed(mnemonic, passphrase=''):
    kdf = bootstrap.PBKDF2HMAC(bootstrap.hashes.SHA512(), length=64, salt=('mnemonic' + passphrase).encode(), iterations=2048)
    return kdf.derive(mnemonic.encode())

def derive_wallet_from_seed(seed_bytes, path="m/44'/60'/0'/0/0"):
    if bootstrap.bip32utils is None:
        bootstrap.sys.stderr.write('[WALLET] FATAL: bip32utils is required for seed-phrase derivation (refusing to derive an incompatible wallet)\n')
        bootstrap.sys.stderr.flush()
        bootstrap.sys.exit(1)
    master = bootstrap.bip32utils.BIP32Key.fromEntropy(seed_bytes)
    parts = path[2:].split('/')
    key = master
    for part in parts:
        if part.endswith("'"):
            index = int(part[:-1]) + 2147483648
        else:
            index = int(part)
        key = key.ChildKey(index)
    priv_bytes = key.PrivateKey()
    priv_int = int.from_bytes(priv_bytes, 'big')
    priv_key = bootstrap.ec.derive_private_key(priv_int, bootstrap.ec.SECP256K1())
    pub = priv_key.public_key()
    pub_bytes = pub.public_bytes(bootstrap.serialization.Encoding.X962, bootstrap.serialization.PublicFormat.UncompressedPoint)
    pub_hex = pub_bytes.hex()
    return (util.pubkey_to_address(pub_hex), priv_bytes.hex(), pub_hex)

def encrypt_private_key(priv_hex, password):
    salt = bootstrap.os.urandom(16)
    kdf = bootstrap.PBKDF2HMAC(bootstrap.hashes.SHA256(), length=32, salt=salt, iterations=100000)
    key = kdf.derive(password.encode())
    nonce = bootstrap.os.urandom(12)
    encryptor = bootstrap.Cipher(bootstrap.algorithms.AES(key), bootstrap.modes.GCM(nonce)).encryptor()
    encrypted = encryptor.update(priv_hex.encode()) + encryptor.finalize()
    argon_h = bootstrap.ph.hash(password) if bootstrap.ph else bootstrap.hashlib.sha256((password + salt.hex()).encode()).hexdigest()
    return {'salt': bootstrap.base64.b64encode(salt).decode(), 'nonce': bootstrap.base64.b64encode(nonce).decode(), 'data': bootstrap.base64.b64encode(encrypted + encryptor.tag).decode(), 'argon2_hash': argon_h}

def decrypt_private_key(encrypted, password):
    try:
        if bootstrap.ph and str(encrypted.get('argon2_hash', '')).startswith('$argon2'):
            bootstrap.ph.verify(encrypted['argon2_hash'], password)
        elif 'argon2_hash' in encrypted:
            salt_hex = bootstrap.base64.b64decode(encrypted['salt']).hex()
            expected = bootstrap.hashlib.sha256((password + salt_hex).encode()).hexdigest()
            if not bootstrap.hmac.compare_digest(str(encrypted['argon2_hash']), expected):
                raise ValueError('Invalid password')
    except Exception:
        raise ValueError('Invalid password')
    salt = bootstrap.base64.b64decode(encrypted['salt'])
    data = bootstrap.base64.b64decode(encrypted['data'])
    kdf = bootstrap.PBKDF2HMAC(bootstrap.hashes.SHA256(), length=32, salt=salt, iterations=100000)
    key = kdf.derive(password.encode())
    if 'nonce' in encrypted:
        nonce = bootstrap.base64.b64decode(encrypted['nonce'])
        ct, tag = (data[:-16], data[-16:])
        decryptor = bootstrap.Cipher(bootstrap.algorithms.AES(key), bootstrap.modes.GCM(nonce, tag)).decryptor()
        try:
            return (decryptor.update(ct) + decryptor.finalize()).decode()
        except Exception:
            raise ValueError('Invalid password')
    iv = bootstrap.base64.b64decode(encrypted['iv'])
    cipher = bootstrap.Cipher(bootstrap.algorithms.AES(key), bootstrap.modes.CBC(iv))
    decryptor = cipher.decryptor()
    decrypted = decryptor.update(data) + decryptor.finalize()
    unpadder = bootstrap.PKCS7(128).unpadder()
    return (unpadder.update(decrypted) + unpadder.finalize()).decode()

def _keccak(data: bytes) -> bytes:
    return bootstrap.eth_keccak(data)

def sha3_keccak_f(state):
    round_constants = [1, 32898, 9223372036854808714, 9223372039002292224, 32907, 2147483649, 9223372039002292353, 9223372039002292233, 138, 136, 2147516425, 2147483658, 2147516555, 9223372036854775947, 9223372036854808713, 9223372036854808579, 9223372036854808578, 9223372036854775936, 32778, 9223372036854775818, 9223372039002292353, 9223372039002292352, 1, 9223372036854808584]
    for round in range(24):
        C = [state[x] ^ state[x + 5] ^ state[x + 10] ^ state[x + 15] ^ state[x + 20] for x in range(5)]
        D = [C[(x + 4) % 5] ^ (C[(x + 1) % 5] << 1 | C[(x + 1) % 5] >> 63) & 18446744073709551615 for x in range(5)]
        for x in range(5):
            for y in range(5):
                state[x + 5 * y] ^= D[x]
        x, y = (1, 0)
        current = state[x + 5 * y]
        for t in range(24):
            x, y = (y, (2 * x + 3 * y) % 5)
            shift = (t + 1) * (t + 2) // 2 % 64
            next_val = state[x + 5 * y]
            state[x + 5 * y] = (current << shift | current >> 64 - shift) & (1 << 64) - 1
            current = next_val
        for y in range(5):
            row = [state[x + 5 * y] for x in range(5)]
            for x in range(5):
                state[x + 5 * y] = row[x] ^ ~row[(x + 1) % 5] & row[(x + 2) % 5]
        state[0] ^= round_constants[round]

def keccak_256(data: bytes) -> bytes:
    return bootstrap.eth_keccak(data)
